import { Command } from 'commander';
import axios from 'axios';
import ora from 'ora';
import os from 'os';
import pkg from '../../package.json' with { type: 'json' };
import { readConfig } from '../utils/config.js';
import { loadHistory } from '../utils/history.js';

export function registerSync(program: Command) {
  program
    .command('sync')
    .description('Sync command history and aliases to cloud backend')
    .action(async () => {
      const cfg = readConfig();
      if (!cfg.cloudSync?.enabled) {
        console.log('Cloud sync disabled in config.');
        return;
      }
      if (!cfg.cloudSync?.endpoint) {
        console.log('Cloud sync endpoint missing in config.');
        return;
      }
      const spinner = ora('Syncing history...').start();
      const payload = {
        history: loadHistory(),
        timestamp: Date.now(),
        machine: os.hostname(),
        platform: `${os.platform()}-${os.arch()}`,
        version: pkg.version
      };
      const headers = {
        'Content-Type': 'application/json',
        ...(cfg.cloudSync.headers || {}),
        ...(cfg.cloudSync.apiKey ? { Authorization: `Bearer ${cfg.cloudSync.apiKey}` } : {})
      };
      try {
        const res = await axios.post(cfg.cloudSync.endpoint, payload, { headers, timeout: 10_000 });
        const id = res.data?.id || res.data?.syncId;
        spinner.succeed(`Synced ${payload.history.length} records to ${cfg.cloudSync.endpoint}${id ? ` (id: ${id})` : ''}`);
      } catch (err) {
        spinner.fail('Cloud sync failed.');
        console.error(err instanceof Error ? err.message : err);
        process.exitCode = 1;
      }
    });
}
